PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry conv2d_nchw_bias(
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 bias_ptr,
    .param .u64 output_ptr,
    .param .u32 N,
    .param .u32 Cin,
    .param .u32 H,
    .param .u32 W,
    .param .u32 Cout,
    .param .u32 kH,
    .param .u32 kW,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .u32 pad_h,
    .param .u32 pad_w,
    .param .u32 outH,
    .param .u32 outW
)
{
    .reg .pred p, p1, p2, p3, p4;
    .reg .b32 r_tid_x, r_tid_y, r_bid_x, r_bid_y, r_bid_z;
    .reg .b32 r_ntid_x, r_ntid_y;
    .reg .u32 r_ow, r_oh, r_outW, r_outH;
    .reg .u32 r_Cout, r_Cin, r_H, r_W, r_kH, r_kW, r_stride_h, r_stride_w, r_pad_h, r_pad_w, r_N;
    .reg .u32 r_nz, r_n, r_oc;
    .reg .u32 r_ic, r_kh, r_kw;
    .reg .u32 r_t0, r_t1, r_t2, r_t3, r_t4, r_t5, r_t6, r_t7;
    .reg .s32 s_oh, s_ow, s_stride_h, s_stride_w, s_pad_h, s_pad_w, s_H, s_W, s_ih, s_iw, s_tmp1, s_tmp2, s_kh, s_kw;
    .reg .b64 in_ptr, w_ptr, b_ptr, out_ptr, addr, addr2, off64;
    // Additional registers for shared-memory tiling
    .reg .b32 r_oh0, r_ow0, r_lin, r_stride_blk, r_i, r_tile_y, r_tile_x;
    .reg .b32 r_oh_off, r_ow_off, r_tile_ih, r_tile_iw, r_ii, r_tmp;
    .reg .s32 s_oh0, s_ow0, s_ih_base, s_iw_base, s_ihL, s_iwL;
    .reg .b64 sbase, saddr, in_ic_base;
    .reg .f32 f_sum, f_in, f_w, f_tmp;
    // Shared memory tile for input: 74 x 74 floats = 5476 * 4 bytes = 21904 bytes
    .shared .align 16 .b8 s_in[21904];
    // Load pointers
    ld.param.u64 in_ptr,    [input_ptr];
    ld.param.u64 w_ptr,     [weight_ptr];
    ld.param.u64 b_ptr,     [bias_ptr];
    ld.param.u64 out_ptr,   [output_ptr];
    // Load dimensions / params
    ld.param.u32 r_N,        [N];
    ld.param.u32 r_Cin,      [Cin];
    ld.param.u32 r_H,        [H];
    ld.param.u32 r_W,        [W];
    ld.param.u32 r_Cout,     [Cout];
    ld.param.u32 r_kH,       [kH];
    ld.param.u32 r_kW,       [kW];
    ld.param.u32 r_stride_h, [stride_h];
    ld.param.u32 r_stride_w, [stride_w];
    ld.param.u32 r_pad_h,    [pad_h];
    ld.param.u32 r_pad_w,    [pad_w];
    ld.param.u32 r_outH,     [outH];
    ld.param.u32 r_outW,     [outW];
    // Thread/block indices
    mov.u32 r_tid_x, %tid.x;
    mov.u32 r_tid_y, %tid.y;
    mov.u32 r_bid_x, %ctaid.x;
    mov.u32 r_bid_y, %ctaid.y;
    mov.u32 r_bid_z, %ctaid.z;
    mov.u32 r_ntid_x, %ntid.x;
    mov.u32 r_ntid_y, %ntid.y;
    mad.lo.u32 r_ow, r_bid_x, r_ntid_x, r_tid_x;
    mad.lo.u32 r_oh, r_bid_y, r_ntid_y, r_tid_y;
    // Compute block origin in output space (ow0, oh0)
    mul.lo.u32 r_ow0, r_bid_x, r_ntid_x;
    mul.lo.u32 r_oh0, r_bid_y, r_ntid_y;
    // Decompose n and oc from blockIdx.z
    mov.u32 r_nz, r_bid_z;
    div.u32 r_n, r_nz, r_Cout;
    rem.u32 r_oc, r_nz, r_Cout;
