    cvt.s32.u32 s_oh, r_oh;
    cvt.s32.u32 s_ow, r_ow;
    cvt.s32.u32 s_stride_h, r_stride_h;
    cvt.s32.u32 s_stride_w, r_stride_w;
    cvt.s32.u32 s_pad_h, r_pad_h;
    cvt.s32.u32 s_pad_w, r_pad_w;
    cvt.s32.u32 s_H, r_H;
    cvt.s32.u32 s_W, r_W;
    // Also compute signed block origins and input tile base coords
    cvt.s32.u32 s_oh0, r_oh0;
    cvt.s32.u32 s_ow0, r_ow0;
    // ih_base = oh0*stride_h - pad_h
    mul.lo.s32 s_tmp1, s_oh0, s_stride_h;
    sub.s32    s_ih_base, s_tmp1, s_pad_h;
    // iw_base = ow0*stride_w - pad_w
    mul.lo.s32 s_tmp2, s_ow0, s_stride_w;
    sub.s32    s_iw_base, s_tmp2, s_pad_w;
