    mad.lo.u32 r_lin, r_tid_y, r_ntid_x, r_tid_x;     // r_lin = tid_y * ntid_x + tid_x
    mul.lo.u32 r_stride_blk, r_ntid_x, r_ntid_y;      // total threads per block
