    mov.u32 r_ic, 0;
IC_LOOP:
    setp.ge.u32 p, r_ic, r_Cin;
    @p bra IC_END;
    // Compute base address for this (n, ic) input plane: ((n*Cin + ic)*H*W)*4 + in_ptr
    mad.lo.u32 r_t0, r_n,  r_Cin, r_ic;     // n*Cin + ic
    mul.lo.u32 r_t1, r_t0, r_H;             // (n*Cin + ic)*H
    mul.lo.u32 r_t2, r_t1, r_W;             // *W
    mul.wide.u32 off64, r_t2, 4;
    add.s64 in_ic_base, in_ptr, off64;
    // Cooperative load of input tile [74 x 74] into shared memory for this ic
    // Cooperative load of input tile [74 x 74] into shared memory for this ic (2D mapping, no div/mod)
    mov.u32 r_tile_y, r_tid_y;
TY_LOOP:
    setp.ge.u32 p, r_tile_y, 74;
    @p bra LOAD_TILE_DONE;
    mov.u32 r_tile_x, r_tid_x;
TX_LOOP:
    setp.ge.u32 p, r_tile_x, 74;
    @p bra TX_END;
    // Global input coordinates for this tile element
    cvt.s32.u32 s_tmp1, r_tile_y;
    add.s32 s_ihL, s_ih_base, s_tmp1;      // s_ihL = ih_base + tile_y
    cvt.s32.u32 s_tmp2, r_tile_x;
    add.s32 s_iwL, s_iw_base, s_tmp2;      // s_iwL = iw_base + tile_x
    // OOB checks
    setp.lt.s32 p1, s_ihL, 0;
    setp.lt.s32 p2, s_iwL, 0;
    setp.ge.s32 p3, s_ihL, s_H;
    setp.ge.s32 p4, s_iwL, s_W;
    or.pred p, p1, p2;
    or.pred p, p,  p3;
    or.pred p, p,  p4;
    @p bra TILE_ZERO_2D;
    // In-bounds: load from global memory
    cvt.u32.s32 r_t3, s_ihL;          // ih
    cvt.u32.s32 r_t4, s_iwL;          // iw
    mad.lo.u32 r_t5, r_t3, r_W, r_t4; // ih*W + iw
    mul.wide.u32 off64, r_t5, 4;
    add.s64 addr, in_ic_base, off64;
    ld.global.f32 f_tmp, [addr];
    bra TILE_STORE_2D;
TILE_ZERO_2D:
    mov.f32 f_tmp, 0f00000000;
TILE_STORE_2D:
    // Store to shared memory at index (tile_y*74 + tile_x)
    mul.lo.u32 r_ii, r_tile_y, 74;
    add.u32 r_ii, r_ii, r_tile_x;
    mul.wide.u32 off64, r_ii, 4;
    add.s64 saddr, sbase, off64;
    st.shared.f32 [saddr], f_tmp;
    // Next tile_x
    add.u32 r_tile_x, r_tile_x, r_ntid_x;
    bra TX_LOOP;
TX_END:
    // Next tile_y
    add.u32 r_tile_y, r_tile_y, r_ntid_y;
    bra TY_LOOP;
LOAD_TILE_DONE:
    // Ensure tile is fully populated before using
    bar.sync 0;
    // Initialize loop counters for kh and kw
    mov.u32 r_kh, 0;
KH_LOOP:
    setp.ge.u32 p, r_kh, r_kH;
    @p bra KH_END;
    mov.u32 r_kw, 0;
KW_LOOP:
    setp.ge.u32 p, r_kw, r_kW;
    @p bra KW_END;
    // Compute shared-memory tile indices for this thread's (oh, ow) and current (kh, kw)
    sub.u32 r_oh_off, r_oh, r_oh0;                   // oh - oh0
    sub.u32 r_ow_off, r_ow, r_ow0;                   // ow - ow0
    mad.lo.u32 r_tile_ih, r_oh_off, r_stride_h, r_kh; // (oh - oh0)*stride_h + kh
    mad.lo.u32 r_tile_iw, r_ow_off, r_stride_w, r_kw; // (ow - ow0)*stride_w + kw
    // ii = tile_ih * 74 + tile_iw
    mul.lo.u32 r_ii, r_tile_ih, 74;
    add.u32 r_ii, r_ii, r_tile_iw;
    mul.wide.u32 off64, r_ii, 4;
    add.s64 saddr, sbase, off64;
    ld.shared.f32 f_in, [saddr];
    // Load weight
    mad.lo.u32 r_t5, r_oc, r_Cin, r_ic;   // oc*Cin + ic
