_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_nchw_bias")

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        # Match the reference constructor and parameters exactly.
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

    def forward(self, x: torch.Tensor):
        assert x.is_cuda, "Input must be on CUDA device"
        assert x.dtype == torch.float32, "Only float32 is supported"
        N, Cin, H, W = x.shape
        Cout = 96
        kH = 11
        kW = 11
        stride_h = 4
        stride_w = 4
        pad_h = 2
        pad_w = 2
        outH = (H + 2 * pad_h - kH) // stride_h + 1
        outW = (W + 2 * pad_w - kW) // stride_w + 1
        y = torch.empty((N, Cout, outH, outW), device=x.device, dtype=x.dtype)

        module = _get_ptx_module()

        block_x = 16
        block_y = 16
        grid_x = (outW + block_x - 1) // block_x
        grid_y = (outH + block_y - 1) // block_y
        grid_z = N * Cout

        module.launch(
            "conv2d_nchw_bias",
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, 1),
            arguments=[
                x, self.conv1.weight, self.conv1.bias, y,
                i32(N), i32(Cin), i32(H), i32(W),
                i32(Cout), i32(kH), i32(kW),
                i32(stride_h), i32(stride_w),
                i32(pad_h), i32(pad_w),
                i32(outH), i32(outW),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

